/**
 * 1024x512 equirectangular land mask (1 bit per cell, row-major from the north-west corner),
 * generated from Natural Earth 1:50m land (public domain) via the world-atlas package.
 */
export const LAND_MASK_WIDTH = 1024;
export const LAND_MASK_HEIGHT = 512;
const LAND_MASK_BASE64 =
  "";

let bits: Uint8Array | null = null;

function decode(): Uint8Array {
  if (bits) return bits;
  const raw = typeof atob === "function" ? atob(LAND_MASK_BASE64) : Buffer.from(LAND_MASK_BASE64, "base64").toString("binary");
  const out = new Uint8Array(raw.length);
  for (let index = 0; index < raw.length; index += 1) out[index] = raw.charCodeAt(index);
  bits = out;
  return out;
}

export function isLand(lat: number, lng: number): boolean {
  const data = decode();
  const x = Math.min(LAND_MASK_WIDTH - 1, Math.max(0, Math.floor(((lng + 180) / 360) * LAND_MASK_WIDTH)));
  const y = Math.min(LAND_MASK_HEIGHT - 1, Math.max(0, Math.floor(((90 - lat) / 180) * LAND_MASK_HEIGHT)));
  const index = y * LAND_MASK_WIDTH + x;
  return (data[index >> 3] & (1 << (index & 7))) !== 0;
}
